  Lu = `Vytvoří žádost na podporu systému Steamworks s prosbou o provedení kontroly stránky výprodeje. Proveďte teprve, až finalizujete grafické i textové prvky a dokončíte seznam zahrnutých her.`,
  Ru = `Ujistěte se, že je navrchu stránky jasně uveden název výprodeje a jeho účel. Pro výprodeje spojené s výstavami se hodí zahrnout textovou sekci, kde výstavu a její fungování krátce představíte.`,
  zu = `S dokončením kontroly dojde také k uzamčení stránky. Pokud budete po kontrole nebo po zahájení výprodeje potřebovat provést nějaké změny, v komentáři je popište a vysvětlete, proč nemohly být provedeny ještě před kontrolou.`,
