  vV = `Nepodsouvejte svým zákazníkům pouze jednu kategorii a místo toho je nechte vybrat takovou, která podle nich Vaší hře sedí nejvíc. Událost bude v každém případě obsahovat odkaz na stránku s nominacemi.`,
  yV = `Žádná kategorie`,
  bV = `Ať už z důvodu skvělé hratelnosti, podmanivého příběhu, propracovaných postav, jedinečného vizuálu nebo návykového multiplayeru, tahle hra zkrátka dominovala roku 2020 a bude se na ni ještě dlouho vzpomínat.`,
  xV = `VR hra roku nebyla jen rozptýlením od běžné reality. Ne, tahle hra realitu vylepšila a za pomoci dospívajícího média posunula hranice virtuálních světů.`,
  SV = `Tahle hra už má něco za sebou, ale přestože roky plynou a kolem se rodí nové a zanikají staré hry, na tuhle tvůrci nezanevřeli a stále, i po všech těch letech, ji jako milující rodiče opatrují, vylepšují a přidávají do ní další obsah.`,
  CV = `Některé hry nejsou to pravé, když je hrajete sami. Někdy zkrátka potřebujete parťáka. Ať už takového, co Vám bude krýt záda, nebo takového, co do zad střelíte, ale pořád zůstanete kamarády. A tohle ocenění je právě pro hru, která je nejlepší ve více lidech.`,
  wV = `Vývojáři této hry se rozhodli nejít cestou nudného fotorealismu, nýbrž někde na začátku zahnuli a pro své dílo vytvořili jedinečný vzhled doprovázený nepopsatelným feelingem.`,
  TV = `Tahle hra je synonymem pro experimentování a prostřednictvím své jedinečné hratelnosti či nevídaných mechanik nabídla zcela nový druh videoherní zábavy, který překvapil i ty nejzkušenější pařany.`,
  EV = `Tahle hra odměňuje vytrvalost a není pro pařany se slabými nervy. Možná jste u ní vzteky rozšlapali klávesnici, ale pořád ji svým způsobem milujete.`,
  DV = `Hudební doprovod této hry Vás málem donutil upgradovat zvukovou kartu nebo si rovnou domů nakvartýrovat orchestr. Tak dobrý totiž byl! `,
  OV = `Jsou dny, kdy se u her chceme odreagovat. Ale jsou také dny, kdy máme chuť na pořádně hutný příběh. Konkrétně tahle hra má příběhu tolik, že by ho mohla rozdávat mexickým telenovelám. Bravo! Takhle už nás dlouho nic nepohltilo.`,
  kV = `Tahle hra je lékem na dny plné stresu – nikam nechvátá, nechává Vás relaxovat a nepřidělává další starosti. Zkrátka taková herní oáza klidu.`,
  AV = `Změnit nominaci?`,
  jV = `Jednu hru můžete nominovat pouze v jedné kategorii, a v této jste už nominovali „%1$s“. Chcete raději nominovat hru „%2$s“?`,
