  LV = `Zdá se, že Váš účet je omezený. Abychom zabránili falešným nominacím, musí uživatelé před nominováním utratit v obchodu služby Steam nejméně 5 dolarů (nebo ekvivalent v místní měně). Pro více informací %1$s.`,
