  TH = `Tahle hra je lékem na dny plné stresu – nikam nechvátá, nechává Vás relaxovat a nepřidělává další starosti. Zkrátka taková herní oáza klidu.`,
  EH = `Tahle hra Vás bavila tak moc, že jste ji s\xA0sebou chtěli vzít všude. Tak jste to udělali! A světe div se, všechno, co ji doma dělalo tak návykovou, se na cestách ještě znásobilo.`,
