  aU = `Část III z IV`,
  oU = `Část IV z IV`,
  sU = `Před dávnými časy svolal Nefritový císař všechna zvířata ze svého království a vyhlásil pro ně závod – dvanáct nejrychlejších v rajském paláci bude poctěno zvěčněním v jeho novém kalendáři.

Prvním, kdo překonal řeku do nebeského panství, byla chytrá Krysa. Protože nikdy moc neholdovala plavání, svezla se na hřbetu věrného Buvola, z něhož natěšeně seskočila ještě předtím, než kopyty došlápl na pevnou zem císařovy zahrady.

Pro spolehlivého Buvola nepředstavovala řeka žádný problém a vzhledem k jeho lhostejnosti vůči výsledkům závodu mu nevadilo ani to, že sehrál podstatnou roli ve vítězství Krysy.`,
  cU = `Soběstačný Tygr plaval příliš opatrně, aby překonal Buvola, nicméně jak sám usoudil, lepší třetí místo než žádné.

Zato mrštný Zajíc zkusil štěstí a skočil na plovoucí kládu. Zpočátku nebyla příliš rychlá, ale nakonec se na Zajíce štěstěna přeci jen usmála a jeho improvizovanou loďku popohnal poryv větru.

Letící Drak z výšin zahlédl vesnici v potížích, a tak pochopitelně přistál a pomohl jejím obyvatelům. Ba co víc, dokonce i mocně fouknul do řeky a dodal rychlost Zajícově kládě. Čest znamenala pro Draka víc než vítězství a páté místo mu stačilo.`,
  lU = `Mazaný Had neměl zájem plazit se takovou dálku a nespatřen se tedy omotal kolem předního kopyta Koně.

Když poté Kůň cválal k cílové čáře, Had se uvolnil a vylekal plachého Koně, čímž si na poslední chvíli zajistil šesté místo.`,
  uU = `Koza, Opice a Kohout při závodu spolupracovali, ale jelikož Koza měla na zdárném dokončení největší podíl, bylo jí přenecháno osmé místo. Rozverná Opice doběhla hned za ní a desátý skončil Kohout, který byl pyšný na to, jak se umístili.

Hravý Pes se v řece zajímal především o šplouchání vody a jedenácté místo mu přišlo jako férový obchod za všechnu tu legraci.

Na posledním místě pak skončil moudrý Vepř, jenž se zastavil na svačinu a šlofíka – dobře totiž věděl, že každé zvíře, nezávisle na umístění, se dočká císařovy přízně.`,
  dU = `Změny profilu se projeví po kontrole`,
  fU = `© %1$s Valve Corporation. Všechna práva vyhrazena. Všechny ochranné známky jsou vlastnictvím příslušných subjektů v USA a dalších zemích.`,
